/**
 * Meta descriptions that read well in search results.
 *
 * Google shows roughly 150-160 characters. Longer text is cut mid-word, and very short
 * text (or text that isn't prose at all) usually gets replaced by whatever Google picks
 * from the page. Some imported WordPress posts and pages carry exactly that: a CSS rule,
 * a "Home » ..." breadcrumb trail, or a five-word slogan. These helpers fix that at render
 * time, so the WordPress export (regenerated by a script) can stay as it is.
 */

/** Longest description we emit. */
export const META_DESCRIPTION_MAX = 160;
/** Shorter than this reads as a slogan, not a summary. */
export const META_DESCRIPTION_MIN = 70;

const NAMED_ENTITIES: Readonly<Record<string, string>> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: " ",
  rsquo: "’",
  lsquo: "‘",
  rdquo: "”",
  ldquo: "“",
  mdash: "—",
  ndash: "–",
  hellip: "…",
  middot: "·",
  rarr: "→",
  trade: "™",
  reg: "®",
  copy: "©",
};

function decodeEntities(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (whole, code: string) => {
    if (code[0] === "#") {
      const n = code[1] === "x" || code[1] === "X" ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      return Number.isFinite(n) && n > 0 && n < 0x110000 ? String.fromCodePoint(n) : whole;
    }
    return NAMED_ENTITIES[code.toLowerCase()] ?? whole;
  });
}

/** Collapse whitespace and drop "\n" escapes the WordPress export flattened to a stray "n". */
function tidy(text: string): string {
  return text
    .replace(/\s+/g, " ")
    .replace(/([.!?:])n(?=\s|$)/g, "$1")
    .trim();
}

/** CSS or script text, not prose (".yp-post{max-width:820px;...}"). */
export function looksLikeCode(text: string): boolean {
  const t = text.trim();
  return /^[.#@]?[\w-]+(?:[\s.#>:-][\w-]*)*\s*\{/.test(t) || /\{[^}]*:[^}]*;/.test(t);
}

/** A breadcrumb trail ("Home » AI Tools » ...", "Home > Resources > ..."). */
function isBreadcrumb(text: string): boolean {
  return /^home\s*[»>›/|]/i.test(text.trim());
}

/**
 * First real paragraph of an HTML body: skips <style>/<script>, breadcrumbs and short
 * labels. Returns "" when the body has no paragraph long enough to summarize the page.
 */
export function firstParagraphText(html: string, minLength = 80): string {
  const body = html.replace(/<(style|script|noscript)\b[\s\S]*?<\/\1>/gi, " ");
  for (const match of body.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)) {
    const text = tidy(decodeEntities(match[1].replace(/<[^>]*>/g, " ")));
    if (text.length < minLength || isBreadcrumb(text) || looksLikeCode(text)) continue;
    return text;
  }
  return "";
}

/**
 * Shortens to at most `max` characters: at the last sentence end when that keeps most of
 * the text, otherwise at the last word boundary with an ellipsis. Never cuts mid-word.
 */
export function clampDescription(text: string, max = META_DESCRIPTION_MAX): string {
  const t = tidy(text);
  if (t.length <= max) return t;
  const window = t.slice(0, max);
  const sentenceEnd = Math.max(window.lastIndexOf(". "), window.lastIndexOf("? "), window.lastIndexOf("! "));
  if (sentenceEnd >= max * 0.6) return window.slice(0, sentenceEnd + 1);
  if (/[.!?]$/.test(window) && t[max] === " ") return window;
  const cut = t.slice(0, max - 1);
  const space = cut.lastIndexOf(" ");
  const base = (space > max * 0.5 ? cut.slice(0, space) : cut).replace(/[\s,;:—–-]+$/, "");
  return `${base}…`;
}

/**
 * A usable description for an imported page or post: the stored one when it is real
 * prose of a reasonable length, else the body's first paragraph, clamped to fit.
 */
export function bestDescription(stored: string | undefined, html: string): string {
  const raw = tidy(decodeEntities(stored ?? ""));
  const usable = raw && !looksLikeCode(raw) && !isBreadcrumb(raw) ? raw : "";
  if (usable.length >= META_DESCRIPTION_MIN) return clampDescription(usable);
  const fromBody = firstParagraphText(html);
  if (fromBody) return clampDescription(fromBody);
  return clampDescription(usable || raw.replace(/^home\s*[»>›/|][^.]*$/i, "").trim());
}

/** The first sentence of a paragraph (the whole text when it has no sentence break). */
export function firstSentence(text: string): string {
  const t = tidy(text);
  const match = /^.+?[.!?](?=\s|$)/.exec(t);
  return match ? match[0] : t;
}
